// NULL-tolerant scan buffer for actionLogScanMapperNullable:
// on a LEFT JOIN miss every column comes back NULL, so each field uses the
// nullable version of the column type even when the column itself is NOT NULL.
type actionLogPreloadBuf struct {
	ID          null.Val[int64]
	CharacterID null.Val[int64]
	Round       null.Val[int64]
	Kind        null.Val[string]
	Summary     null.Val[string]
	HPDelta     null.Val[int64]
	Payload     null.Val[string]
	CreatedAt   null.Val[time.Time]
}

// actionLogScanMapperNullable maps the preloaded actionLog
// columns (prefixed with the runtime join alias) without reflection, while
// keeping the LEFT JOIN semantics of the reflection-based mapper: a row whose
// prefixed columns are all NULL yields nil (no child), and NULL values never
// error, they just leave the zero value in the field.
func actionLogScanMapperNullable(prefix string) scan.Mapper[*ActionLog] {
	return func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*ActionLog, error)) {
		// resolve the column names once per query, not per row
		type target struct {
			idx int
			dst func(b *actionLogPreloadBuf) any
		}
		targets := make([]target, 0, 8)
		for i, col := range cols {
			name, ok := strings.CutPrefix(col, prefix)
			if !ok {
				continue
			}
			switch name {
			case "id":
				targets = append(targets, target{i, func(b *actionLogPreloadBuf) any { return &b.ID }})
			case "character_id":
				targets = append(targets, target{i, func(b *actionLogPreloadBuf) any { return &b.CharacterID }})
			case "round":
				targets = append(targets, target{i, func(b *actionLogPreloadBuf) any { return &b.Round }})
			case "kind":
				targets = append(targets, target{i, func(b *actionLogPreloadBuf) any { return &b.Kind }})
			case "summary":
				targets = append(targets, target{i, func(b *actionLogPreloadBuf) any { return &b.Summary }})
			case "hp_delta":
				targets = append(targets, target{i, func(b *actionLogPreloadBuf) any { return &b.HPDelta }})
			case "payload":
				targets = append(targets, target{i, func(b *actionLogPreloadBuf) any { return &b.Payload }})
			case "created_at":
				targets = append(targets, target{i, func(b *actionLogPreloadBuf) any { return &b.CreatedAt }})
			}
		}

		// One scratch buffer reused for every row: before -> scan -> after runs
		// synchronously per row, the scheduled columns are fully overwritten each
		// row, and unselected columns stay zero, so a single buffer preserves the
		// per-row NULL semantics without allocating a buffer per parent row. The
		// returned child (o below) is always freshly allocated, so buf never
		// escapes past the after func.
		buf := new(actionLogPreloadBuf)
		return func(row *scan.Row) (any, error) {
				for _, t := range targets {
					row.ScheduleScanByIndex(t.idx, t.dst(buf))
				}
				return buf, nil
			}, func(link any) (*ActionLog, error) {
				buf := link.(*actionLogPreloadBuf)

				// Same rule as the reflection mapper's row validator: the child
				// exists only if at least one of its columns is not NULL. Columns
				// not selected by the query are never scanned and stay invalid,
				// so this check also matches when only a subset is selected.
				if !buf.ID.IsValue() &&
					!buf.CharacterID.IsValue() &&
					!buf.Round.IsValue() &&
					!buf.Kind.IsValue() &&
					!buf.Summary.IsValue() &&
					!buf.HPDelta.IsValue() &&
					!buf.Payload.IsValue() &&
					!buf.CreatedAt.IsValue() {
					return nil, nil
				}

				o := new(ActionLog)
				if buf.ID.IsValue() {
					o.ID = buf.ID.MustGet()
				}
				if buf.CharacterID.IsValue() {
					o.CharacterID = buf.CharacterID.MustGet()
				}
				if buf.Round.IsValue() {
					o.Round = buf.Round.MustGet()
				}
				if buf.Kind.IsValue() {
					o.Kind = buf.Kind.MustGet()
				}
				if buf.Summary.IsValue() {
					o.Summary = buf.Summary.MustGet()
				}
				if buf.HPDelta.IsValue() {
					o.HPDelta = buf.HPDelta.MustGet()
				}
				if buf.Payload.IsValue() {
					o.Payload = buf.Payload.MustGet()
				}
				if buf.CreatedAt.IsValue() {
					o.CreatedAt = buf.CreatedAt.MustGet()
				}
				return o, nil
			}
	}
}

func (o *ActionLog) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "StepActionCorrections":
		rels, ok := retrieved.(ActionCorrectionSlice)
		if !ok {
			return fmt.Errorf("actionLog cannot load %T as %q", retrieved, name)
		}

		o.R.StepActionCorrections = rels
		o.R.Loaded.StepActionCorrections = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.StepActionLog = o
				rel.R.Loaded.StepActionLog = true
			}
		}
		return nil
	case "ActionActionCorrections":
		rels, ok := retrieved.(ActionCorrectionSlice)
		if !ok {
			return fmt.Errorf("actionLog cannot load %T as %q", retrieved, name)
		}

		o.R.ActionActionCorrections = rels
		o.R.Loaded.ActionActionCorrections = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.ActionActionLog = o
				rel.R.Loaded.ActionActionLog = true
			}
		}
		return nil
	case "Character":
		rel, ok := retrieved.(*Character)
		if !ok {
			return fmt.Errorf("actionLog cannot load %T as %q", retrieved, name)
		}

		o.R.Character = rel
		o.R.Loaded.Character = true

		if rel != nil {
			rel.R.ActionLogs = ActionLogSlice{o}
		}
		return nil
	case "ActionActionSnapshots":
		rels, ok := retrieved.(ActionSnapshotSlice)
		if !ok {
			return fmt.Errorf("actionLog cannot load %T as %q", retrieved, name)
		}

		o.R.ActionActionSnapshots = rels
		o.R.Loaded.ActionActionSnapshots = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.ActionActionLog = o
				rel.R.Loaded.ActionActionLog = true
			}
		}
		return nil
	default:
		return fmt.Errorf("actionLog has no relationship %q", name)
	}
}

type actionLogPreloader struct {
	Character func(...sqlite.PreloadOption) sqlite.Preloader
}

func buildActionLogPreloader() actionLogPreloader {
	return actionLogPreloader{
		Character: func(opts ...sqlite.PreloadOption) sqlite.Preloader {
			return sqlite.Preload[*Character, CharacterSlice](sqlite.PreloadRel{
				Name: "Character",
				Sides: []sqlite.PreloadSide{
					{
						From:        ActionLogs,
						To:          Characters,
						FromColumns: []string{"character_id"},
						ToColumns:   []string{"id"},
					},
				},
			}, Characters.Columns.Names(), characterScanMapperNullable, opts...)
		},
	}
}

