// LoadCharacter loads the actionLog's Character into the .R struct
func (os ActionLogSlice) LoadCharacter(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	characters, err := os.Character(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Character = nil
		o.R.Loaded.Character = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	actionLogByKey := make(map[int64][]*ActionLog, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		actionLogByKey[o.CharacterID] = append(actionLogByKey[o.CharacterID], o)
	}

	for _, rel := range characters {

		owners, ok := actionLogByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.Character != nil {
				continue
			}

			rel.R.ActionLogs = append(rel.R.ActionLogs, o)

			o.R.Character = rel

		}
	}

	return nil
}

